from borg_mcp.cli import main

if __name__ == "__main__":
    main()

"""Configuration loading and validation.

The config file holds all security-relevant settings (repository allowlist,
passcommands, feature toggles). It is trusted admin input, but it is still
validated strictly: a typo must fail loudly at startup, not silently relax a
restriction at tool-call time.
"""

import logging
import os
import re
import stat
import tomllib
from dataclasses import dataclass, field
from pathlib import Path

logger = logging.getLogger(__name__)

DEFAULT_CONFIG_PATHS = (Path("~/.config/borg-mcp/config.toml"), Path("/etc/borg-mcp.toml"))

ALIAS_RE = re.compile(r"^[A-Za-z0-9][A-Za-z0-9._-]*$")
ENV_NAME_RE = re.compile(r"^BORG_[A-Z0-9_]+$")
# secrets belong in passcommand, nothing may inject them as plain env values
ENV_DENYLIST = frozenset({"BORG_PASSPHRASE", "BORG_PASSCOMMAND", "BORG_REPO"})

MIN_TIMEOUT, MAX_TIMEOUT = 1, 86400
MIN_MAX_ITEMS, MAX_MAX_ITEMS = 1, 100000


class ConfigError(Exception):
    """Invalid or missing configuration."""


@dataclass(frozen=True)
class RepoConfig:
    name: str
    location: str
    description: str = ""
    passcommand: str | None = None
    extra_env: dict[str, str] = field(default_factory=dict)


@dataclass(frozen=True)
class ServerConfig:
    repos: dict[str, RepoConfig]
    borg_binary: str = "borg"
    allow_file_listing: bool = False
    timeout: int = 300
    max_items: int = 1000


def find_config(path: str | None) -> Path:
    if path is not None:
        p = Path(path)
        if not p.is_file():
            raise ConfigError(f"config file not found: {p}")
        return p
    for candidate in DEFAULT_CONFIG_PATHS:
        p = candidate.expanduser()
        if p.is_file():
            return p
    raise ConfigError("no config file found (tried: %s)" % ", ".join(str(p) for p in DEFAULT_CONFIG_PATHS))


def _check_keys(what: str, table: dict, allowed: set[str]) -> None:
    unknown = set(table) - allowed
    if unknown:
        raise ConfigError(f"{what}: unknown key(s): {', '.join(sorted(unknown))}")


def _typed(what: str, table: dict, key: str, typ: type, default):
    value = table.get(key, default)
    if not isinstance(value, typ) or (typ is int and isinstance(value, bool)):
        raise ConfigError(f"{what}: {key} must be of type {typ.__name__}")
    return value


def _load_repo(name: str, table: object) -> RepoConfig:
    what = f"repos.{name}"
    if not ALIAS_RE.match(name):
        raise ConfigError(f"invalid repository alias {name!r} (allowed: letters, digits, '.', '_', '-')")
    if not isinstance(table, dict):
        raise ConfigError(f"{what}: must be a table")
    _check_keys(what, table, {"location", "description", "passcommand", "extra_env"})
    location = _typed(what, table, "location", str, "")
    if not location:
        raise ConfigError(f"{what}: location is required")
    description = _typed(what, table, "description", str, "")
    passcommand = table.get("passcommand")
    if passcommand is not None and (not isinstance(passcommand, str) or not passcommand):
        raise ConfigError(f"{what}: passcommand must be a non-empty string")
    extra_env = _typed(what, table, "extra_env", dict, {})
    for env_name, env_value in extra_env.items():
        if not isinstance(env_value, str):
            raise ConfigError(f"{what}: extra_env.{env_name} must be a string")
        if env_name in ENV_DENYLIST:
            raise ConfigError(f"{what}: extra_env must not set {env_name} (use passcommand for secrets)")
        if not ENV_NAME_RE.match(env_name):
            raise ConfigError(f"{what}: extra_env only allows BORG_* variables, got {env_name!r}")
    return RepoConfig(
        name=name, location=location, description=description, passcommand=passcommand, extra_env=dict(extra_env)
    )


def _check_permissions(path: Path) -> None:
    mode = path.stat().st_mode
    if mode & (stat.S_IWGRP | stat.S_IWOTH):
        logger.warning("config file %s is group/world-writable - it should only be writable by its owner", path)
    if mode & stat.S_IROTH:
        logger.warning("config file %s is world-readable - it may reveal repository locations", path)


def load_config(path: Path) -> ServerConfig:
    try:
        with path.open("rb") as f:
            data = tomllib.load(f)
    except OSError as e:
        raise ConfigError(f"cannot read config file {path}: {e}") from e
    except tomllib.TOMLDecodeError as e:
        raise ConfigError(f"invalid TOML in {path}: {e}") from e
    _check_permissions(path)
    _check_keys(str(path), data, {"server", "repos"})
    server = data.get("server", {})
    if not isinstance(server, dict):
        raise ConfigError("server: must be a table")
    _check_keys("server", server, {"borg_binary", "allow_file_listing", "timeout", "max_items"})
    borg_binary = _typed("server", server, "borg_binary", str, "borg")
    if not borg_binary:
        raise ConfigError("server: borg_binary must be a non-empty string")
    allow_file_listing = _typed("server", server, "allow_file_listing", bool, False)
    timeout = _typed("server", server, "timeout", int, 300)
    if not MIN_TIMEOUT <= timeout <= MAX_TIMEOUT:
        raise ConfigError(f"server: timeout must be in [{MIN_TIMEOUT}, {MAX_TIMEOUT}]")
    max_items = _typed("server", server, "max_items", int, 1000)
    if not MIN_MAX_ITEMS <= max_items <= MAX_MAX_ITEMS:
        raise ConfigError(f"server: max_items must be in [{MIN_MAX_ITEMS}, {MAX_MAX_ITEMS}]")
    repos_table = data.get("repos", {})
    if not isinstance(repos_table, dict) or not repos_table:
        raise ConfigError("config must define at least one repository in [repos.<alias>]")
    repos = {name: _load_repo(name, table) for name, table in repos_table.items()}
    return ServerConfig(
        repos=repos,
        borg_binary=borg_binary,
        allow_file_listing=allow_file_listing,
        timeout=timeout,
        max_items=max_items,
    )


def base_env() -> dict[str, str]:
    """Minimal environment for borg subprocesses.

    Nothing from the parent environment leaks through except what borg needs
    to run (PATH, HOME, ...) - especially no BORG_* variables the operator may
    have set in their own shell.
    """
    keep = ("PATH", "HOME", "USER", "LOGNAME", "TMPDIR", "LANG", "LC_ALL", "LC_CTYPE", "SSH_AUTH_SOCK")
    return {k: os.environ[k] for k in keep if k in os.environ}


def repo_env(repo: RepoConfig) -> dict[str, str]:
    env = base_env()
    env.update(repo.extra_env)
    if repo.passcommand:
        env["BORG_PASSCOMMAND"] = repo.passcommand
    return env

"""borg2 command templates - the complete allowlist of what borg-mcp may execute.

Values originating from the MCP client (the agent) are validated here and only
ever placed in ``--option=value`` form or as strictly checked positionals, so
borg's argument parser can never mistake them for additional options.
"""

MAX_VALUE_LEN = 200
MAX_LIST_LIMIT = 100000
MAX_KEEP = 10000

# the retention rules prune_preview accepts, in borg's --keep-<rule> spelling
KEEP_RULES = ("secondly", "minutely", "hourly", "daily", "weekly", "monthly", "yearly")


class ValidationError(Exception):
    """An agent-supplied value was rejected."""


def _checked_str(value, what: str) -> str:
    if not isinstance(value, str):
        raise ValidationError(f"{what} must be a string")
    if not 0 < len(value) <= MAX_VALUE_LEN:
        raise ValidationError(f"{what} must be 1..{MAX_VALUE_LEN} characters")
    if value.startswith("-"):
        raise ValidationError(f"{what} must not start with '-'")
    if any(ord(c) < 32 or ord(c) == 127 for c in value):
        raise ValidationError(f"{what} must not contain control characters")
    return value


def _checked_int(value, what: str) -> int:
    if isinstance(value, bool) or not isinstance(value, int):
        raise ValidationError(f"{what} must be an integer")
    if not 1 <= value <= MAX_LIST_LIMIT:
        raise ValidationError(f"{what} must be in 1..{MAX_LIST_LIMIT}")
    return value


def version_cmd() -> list[str]:
    return ["--version"]


def repo_info_cmd() -> list[str]:
    return ["repo-info", "--json"]


def _checked_match(value, what: str) -> str:
    value = _checked_str(value, what)
    # borg's re: patterns run Python regexes on the server - a crafted pattern with
    # catastrophic backtracking would let the agent burn CPU (ReDoS). Globs suffice.
    if value.startswith("re:") or ":re:" in value:
        raise ValidationError(f"{what}: regular expression patterns (re:) are not allowed, use sh: globs")
    return value


def repo_list_cmd(match: str | None = None, first: int | None = None, last: int | None = None) -> list[str]:
    if first is not None and last is not None:
        raise ValidationError("give either first or last, not both")
    cmd = ["repo-list", "--json"]
    if match is not None:
        cmd.append(f"--match-archives={_checked_match(match, 'match')}")
    if first is not None:
        cmd.append(f"--first={_checked_int(first, 'first')}")
    if last is not None:
        cmd.append(f"--last={_checked_int(last, 'last')}")
    return cmd


def archive_info_cmd(archive: str) -> list[str]:
    return ["info", "--json", _checked_str(archive, "archive")]


def latest_archive_cmd() -> list[str]:
    return ["info", "--json", "--last=1"]


def prune_preview_cmd(keep: dict[str, int]) -> list[str]:
    """Build a prune command that can only ever be a dry run.

    "--dry-run" is part of the template and is never derived from an argument:
    borg-mcp must not be able to actually prune, whatever the client asks for.
    """
    cmd = ["prune", "--dry-run", "--list", "--json"]
    unknown = set(keep) - set(KEEP_RULES)
    if unknown:
        raise ValidationError(f"unknown keep rule(s): {', '.join(sorted(unknown))}")
    if not keep:
        raise ValidationError(f"at least one keep rule is required, one of: {', '.join(KEEP_RULES)}")
    for rule in KEEP_RULES:  # fixed order, independent of client input
        if rule not in keep:
            continue
        value = keep[rule]
        if isinstance(value, bool) or not isinstance(value, int):
            raise ValidationError(f"keep_{rule} must be an integer")
        if not 0 <= value <= MAX_KEEP:
            raise ValidationError(f"keep_{rule} must be in 0..{MAX_KEEP}")
        cmd.append(f"--keep-{rule}={value}")
    return cmd


def list_archive_cmd(archive: str, path_prefix: str | None = None) -> list[str]:
    cmd = ["list", "--json-lines", _checked_str(archive, "archive")]
    if path_prefix is not None:
        # "pp:" (path prefix) makes borg treat the value literally: a selector the
        # agent tries to smuggle in ("re:...") becomes part of the path, not a pattern
        cmd.append(f"pp:{_checked_str(path_prefix, 'path_prefix')}")
    return cmd


def diff_archives_cmd(archive1: str, archive2: str, path_prefix: str | None = None) -> list[str]:
    cmd = ["diff", "--json-lines", _checked_str(archive1, "archive1"), _checked_str(archive2, "archive2")]
    if path_prefix is not None:
        cmd.append(f"pp:{_checked_str(path_prefix, 'path_prefix')}")
    return cmd

try:
    from borg_mcp._version import __version__
except ImportError:
    __version__ = "0.1.dev0"

import json
import textwrap

import pytest

from borg_mcp.config import RepoConfig, ServerConfig

# fake borg: emits canned JSON shaped like borg2 --json output, no repo needed
CANNED_BODY = """\
import datetime, json, sys

args = sys.argv[1:]
if args == ["--version"]:
    print("borg 2.0.0b23")
    sys.exit(0)
sub = args[0]
now = datetime.datetime.now().isoformat()


def arch(name):
    return {
        "name": name,
        "id": "aid_" + name,
        "start": now,
        "end": now,
        "hostname": "testhost",
        "username": "tw",
        "command_line": ["borg", "create"],
        "stats": {"nfiles": 3, "original_size": 1000, "compressed_size": 500, "deduplicated_size": 100},
    }


local = {"cache": {"path": "/home/user/.cache/borg/beef"}, "security_dir": "/home/user/.config/borg/security"}
if sub == "repo-info":
    print(json.dumps({"repository": {"id": "beef" * 16, "location": "somewhere"}, **local}))
elif sub == "repo-list":
    print(json.dumps({"archives": [arch("archive1"), arch("archive2")], "repository": {"id": "beef" * 16}}))
elif sub == "info":
    print(json.dumps({"archives": [arch("archive2")], "repository": {"id": "beef" * 16}, **local}))
elif sub == "prune":
    if "--dry-run" not in args:
        sys.stderr.write("FAKE BORG: refusing a real prune" + chr(10))
        sys.exit(99)
    print(json.dumps({"archives": [
        dict(arch("archive2"), kept=True, keep_rule="daily"),
        dict(arch("archive1"), kept=False),
    ]}))
elif sub == "list":
    for i in range(5):
        print(json.dumps({"path": "data/file%d.txt" % i, "type": "-", "size": 100 + i, "mtime": now}))
elif sub == "diff":
    print(json.dumps({"path": "data/file1.txt", "changes": [{"type": "modified", "added": 5, "removed": 2}]}))
    print(json.dumps({"path": "data/new.txt", "changes": [{"type": "added"}]}))
else:
    sys.exit(2)
"""


@pytest.fixture
def make_fake_borg(tmp_path):
    """Factory writing an executable fake borg script; returns its path as str."""

    counter = iter(range(100))

    def make(body: str) -> str:
        script = tmp_path / f"fakeborg{next(counter)}"
        script.write_text("#!/usr/bin/env python3\n" + textwrap.dedent(body))
        script.chmod(0o755)
        return str(script)

    return make


@pytest.fixture
def fake_borg(make_fake_borg):
    return make_fake_borg(CANNED_BODY)


@pytest.fixture
def fake_borg_logged(make_fake_borg, tmp_path):
    """Canned fake borg that also logs each invocation's argv; returns (path, argv_log_path)."""
    log = tmp_path / "argv.log"
    body = f"""\
import json, sys
with open({str(log)!r}, "a") as f:
    f.write(json.dumps(sys.argv[1:]) + chr(10))
""" + CANNED_BODY
    return make_fake_borg(body), log


def read_argv_log(log):
    return [json.loads(line) for line in log.read_text().splitlines()]


@pytest.fixture
def repo_config():
    return RepoConfig(name="test", location="/path/to/repo", description="demo repo")


@pytest.fixture
def server_config(fake_borg, repo_config):
    return ServerConfig(repos={"test": repo_config}, borg_binary=fake_borg, timeout=30, max_items=50)


@pytest.fixture
def file_listing_config(fake_borg, repo_config):
    return ServerConfig(
        repos={"test": repo_config}, borg_binary=fake_borg, timeout=30, max_items=50, allow_file_listing=True
    )


@pytest.fixture
def call():
    """Call an MCP tool and return its structured result (asserts success)."""

    async def _call(server, name, arguments):
        result = await server.call_tool(name, arguments)
        assert not result.is_error, f"tool {name} failed: {result.content}"
        sc = result.structured_content
        if isinstance(sc, dict) and set(sc) == {"result"}:
            return sc["result"]
        return sc

    return _call

import pytest

import itertools

from borg_mcp.commands import (
    KEEP_RULES,
    MAX_KEEP,
    ValidationError,
    archive_info_cmd,
    diff_archives_cmd,
    latest_archive_cmd,
    list_archive_cmd,
    prune_preview_cmd,
    repo_info_cmd,
    repo_list_cmd,
    version_cmd,
)


def test_fixed_commands():
    assert version_cmd() == ["--version"]
    assert repo_info_cmd() == ["repo-info", "--json"]
    assert latest_archive_cmd() == ["info", "--json", "--last=1"]


def test_repo_list_plain():
    assert repo_list_cmd() == ["repo-list", "--json"]


def test_repo_list_filters():
    assert repo_list_cmd(match="sh:home-*") == ["repo-list", "--json", "--match-archives=sh:home-*"]
    assert repo_list_cmd(first=3) == ["repo-list", "--json", "--first=3"]
    assert repo_list_cmd(last=5) == ["repo-list", "--json", "--last=5"]


def test_repo_list_first_and_last():
    with pytest.raises(ValidationError, match="not both"):
        repo_list_cmd(first=1, last=1)


def test_archive_info():
    assert archive_info_cmd("my-archive.2026-08-01") == ["info", "--json", "my-archive.2026-08-01"]


@pytest.mark.parametrize(
    "value,message",
    [
        ("-evil", "must not start with '-'"),
        ("--delete", "must not start with '-'"),
        ("a\nb", "control characters"),
        ("a\x00b", "control characters"),
        ("a\x7fb", "control characters"),
        ("", "1..200"),
        ("x" * 201, "1..200"),
        (42, "must be a string"),
    ],
)
def test_bad_string_values(value, message):
    with pytest.raises(ValidationError, match=message):
        archive_info_cmd(value)
    with pytest.raises(ValidationError, match=message):
        repo_list_cmd(match=value)


@pytest.mark.parametrize("value", ["re:(a+)+b", "re:.*", "name:re:x"])
def test_regex_match_rejected(value):
    # re: patterns would run agent-supplied regexes on the server (ReDoS)
    with pytest.raises(ValidationError, match="not allowed"):
        repo_list_cmd(match=value)


@pytest.mark.parametrize("value", ["home", "sh:home-*", "aid:0fae632d", "host:MacBook-Pro-4"])
def test_safe_match_accepted(value):
    assert repo_list_cmd(match=value) == ["repo-list", "--json", f"--match-archives={value}"]


def test_archive_name_none_rejected():
    # None means "not given" for the optional match filter, but never for a required archive name
    with pytest.raises(ValidationError, match="must be a string"):
        archive_info_cmd(None)


@pytest.mark.parametrize("value", [0, -1, 100001, True, "5", 1.5])
def test_bad_int_values(value):
    with pytest.raises(ValidationError):
        repo_list_cmd(first=value)
    with pytest.raises(ValidationError):
        repo_list_cmd(last=value)


def test_list_archive():
    assert list_archive_cmd("arch") == ["list", "--json-lines", "arch"]
    assert list_archive_cmd("arch", "home/tw") == ["list", "--json-lines", "arch", "pp:home/tw"]


def test_diff_archives():
    assert diff_archives_cmd("a1", "a2") == ["diff", "--json-lines", "a1", "a2"]
    assert diff_archives_cmd("a1", "a2", "home") == ["diff", "--json-lines", "a1", "a2", "pp:home"]


@pytest.mark.parametrize("prefix", ["re:(a+)+b", "sh:**", "fm:*", "pp:other"])
def test_path_prefix_selectors_neutralized(prefix):
    # a smuggled selector must end up inside the literal pp: path, not as its own selector
    (arg,) = list_archive_cmd("arch", prefix)[3:]
    assert arg == f"pp:{prefix}"


@pytest.mark.parametrize("value", ["-x", "a\nb", "", "x" * 201])
def test_bad_path_prefix_rejected(value):
    with pytest.raises(ValidationError):
        list_archive_cmd("arch", value)
    with pytest.raises(ValidationError):
        diff_archives_cmd("a1", "a2", value)


@pytest.mark.parametrize("bad", ["--delete", "-x", "a\nb"])
def test_diff_archive_names_validated(bad):
    with pytest.raises(ValidationError):
        diff_archives_cmd(bad, "a2")
    with pytest.raises(ValidationError):
        diff_archives_cmd("a1", bad)


def test_prune_preview():
    assert prune_preview_cmd({"daily": 7}) == ["prune", "--dry-run", "--list", "--json", "--keep-daily=7"]
    assert prune_preview_cmd({"weekly": 4, "daily": 7}) == [
        "prune",
        "--dry-run",
        "--list",
        "--json",
        "--keep-daily=7",
        "--keep-weekly=4",  # fixed order, independent of input order
    ]


def test_prune_always_dry_run():
    """The safety net: no combination of accepted input may produce a real prune."""
    for count in range(1, len(KEEP_RULES) + 1):
        for rules in itertools.combinations(KEEP_RULES, count):
            cmd = prune_preview_cmd(dict.fromkeys(rules, 1))
            assert cmd[0] == "prune"
            assert "--dry-run" in cmd
    # ... and every value a client can get past validation keeps the dry run
    for value in (0, 1, MAX_KEEP):
        assert "--dry-run" in prune_preview_cmd({"daily": value})


def test_prune_needs_a_keep_rule():
    with pytest.raises(ValidationError, match="at least one keep rule"):
        prune_preview_cmd({})


def test_prune_unknown_rule():
    with pytest.raises(ValidationError, match="unknown keep rule"):
        prune_preview_cmd({"daily": 7, "fortnightly": 2})


@pytest.mark.parametrize("value", [-1, MAX_KEEP + 1, "7", 7.0, True, None])
def test_prune_bad_keep_value(value):
    with pytest.raises(ValidationError):
        prune_preview_cmd({"daily": value})


def test_no_option_smuggling_via_match():
    # agent-influenced values always end up in --opt=value form, never as separate argv items
    cmd = repo_list_cmd(match="sh:*")
    assert all(arg.startswith(("repo-list", "--json", "--match-archives=")) for arg in cmd)
